8	import React from 'react';
9	import loadable from '@loadable/component';
10	import { getConfig } from '@salesforce/pwa-kit-runtime/utils/ssr-config';
11	
12	// Components
13	import { Skeleton } from '@salesforce/retail-react-app/app/components/shared/ui';
14	import { configureRoutes } from '@salesforce/retail-react-app/app/utils/routes-utils';
15	import { routes as _routes } from '@salesforce/retail-react-app/app/routes';
16	
17	const fallback = <Skeleton height="75vh" width="100%" />;
18	
19	// Create your pages here and add them to the routes array
20	// Use loadable to split code into smaller js chunks
21	const Home = loadable(() => import('./pages/home'), { fallback });
22	const MyNewRoute = loadable(() => import('./pages/my-new-route'));
23	const Experience = loadable(() => import('./pages/experience'), { fallback });
24	const ContentfulPreview = loadable(() => import('./pages/contentfulPreview'), { fallback });
25	
26	/*
27	 * The PDP override is reached through this explicit entry, not through the overrides
28	 * resolver. That resolver only redirects imports that *name* `@salesforce/retail-react-app`;
29	 * the base `app/routes.jsx` loads its PDP with a relative `import('./pages/product-detail')`,
30	 * which is never redirected. Without the route below, `overrides/app/pages/product-detail`
31	 * is dead code and the base page renders instead.
32	 */
33	const ProductDetail = loadable(() => import('./pages/product-detail'), { fallback });
34	
35	const routes = [
36	  {
37	    path: '/',
38	    component: Home,
39	    exact: true,
40	  },
41	  {
42	    path: '/my-new-route',
43	    component: MyNewRoute,
44	  },
45	  // Must precede `..._routes` — the base array carries its own '/product/:productId'
46	  // entry pointing at the base page, and `configureRoutes` keeps the first match.
47	  {
48	    path: '/product/:productId',
49	    component: ProductDetail,
50	  },
51	  ..._routes,
52	  // Contentful Live Preview — must be before /:slug so it takes priority.
53	  {
54	    path: '/preview',
55	    component: ContentfulPreview,
56	    exact: true,
57	  },
58	  // Contentful Studio/Experience pages — fallback after all SFCC routes.
59	  // `configureRoutes` strips PWA Kit's '*' catch-all so this is safely reached only for paths no other route matched.
60	  {
61	    path: '/:slug',
62	    component: Experience,
63	  },
64	];
65	
66	export default () => {
67	  const config = getConfig();
68	  return configureRoutes(routes, config, {
69	    ignoredRoutes: ['/callback', '*'],
70	  });
71	};
